fn gcd_calc(mut m: u32, mut n: u32) -> u32 {
    // Precondition from the problem: m > 0 && n > 0

    // Ensure m ≥ n so that each m % n < n ≤ m, 
    // hence (m + n) strictly decreases on every loop iteration.
    if m < n {
        std::mem::swap(&mut m, &mut n);
    }

    // Standard Euclidean step:
    //   while n != 0 {
    //     (m, n) := (n, m % n)
    //   }
    // Invariant: gcd(m, n) remains gcd of the original inputs.
    while n != 0 {
        let r = m % n;
        m = n;
        n = r;
    }

    // When n == 0, m is the GCD and > 0
    m
}